/**
 *
 * TreeDropIndicator renders a visual cue (`before` / `inside` / `after` overlay)
 * while a drag-and-drop operation is in progress over a node.
 *
 * [Live Demo](https://www.primereact.org/tree/)
 *
 * @module TreeDropIndicator
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { TreeRootInstance } from './TreeRoot.types';
/**
 * Defines passthrough(pt) options type in TreeDropIndicator component.
 */
export type TreeDropIndicatorPassThroughType<E> = PassThroughType<TreeDropIndicatorInstance, E>;
/**
 * Defines passthrough(pt) options of TreeDropIndicator component.
 */
export interface TreeDropIndicatorPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TreeDropIndicatorPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in TreeDropIndicator component.
 */
export interface TreeDropIndicatorProps extends BaseComponentProps<TreeDropIndicatorInstance, unknown, TreeDropIndicatorPassThrough> {
    /**
     * Which drop point this indicator represents. Render two siblings of
     * `Tree.Content` — one with `position="before"` and one with `position="after"`.
     * Each renders only while its respective drop point is active.
     * @defaultValue 'before'
     */
    position?: 'before' | 'after';
}
/**
 * Defines valid state in TreeDropIndicator component.
 */
export interface TreeDropIndicatorState {
}
/**
 * Defines the methods and properties exposed by TreeDropIndicator component.
 */
export interface TreeDropIndicatorExposes {
    /**
     * The Tree component instance.
     */
    tree: TreeRootInstance | undefined | null;
}
/**
 * Instance of TreeDropIndicator component.
 */
export type TreeDropIndicatorInstance = ComponentInstance<TreeDropIndicatorProps, TreeDropIndicatorState, TreeDropIndicatorExposes>;
